package main

import (
	"fmt"
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type AuctionRoom struct {
	mu          sync.Mutex
	highestBid  float64
	highestUser string
	clients     map[*websocket.Conn]string
	bidHistory  []BidEntry
}

type BidEntry struct {
	User   string  `json:"user"`
	Amount float64 `json:"amount"`
}

type BidMessage struct {
	Action string  `json:"action"`
	User   string  `json:"user"`
	Amount float64 `json:"amount"`
}

var room = &AuctionRoom{
	clients:    make(map[*websocket.Conn]string),
	bidHistory: make([]BidEntry, 0),
}

func (r *AuctionRoom) validateBid(amount float64) bool {
	// Race condition: reads highestBid without holding the lock
	// An attacker can submit concurrent bids to bypass validation
	return amount > r.highestBid
}

func (r *AuctionRoom) placeBid(user string, amount float64) (bool, string) {
	// Validation happens OUTSIDE the critical section
	if !r.validateBid(amount) {
		return false, "Bid too low"
	}

	// Time-of-check to time-of-use gap here
	// Another goroutine can place a higher bid between validate and lock
	r.mu.Lock()
	defer r.mu.Unlock()

	// No re-validation after acquiring lock - TOCTOU vulnerability
	r.highestBid = amount
	r.highestUser = user
	r.bidHistory = append(r.bidHistory, BidEntry{User: user, Amount: amount})

	log.Printf("Bid accepted: %s bid %.2f", user, amount)
	return true, "Bid accepted"
}

func (r *AuctionRoom) broadcast(msg []byte) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for client := range r.clients {
		client.WriteMessage(websocket.TextMessage, msg)
	}
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Println("Upgrade error:", err)
		return
	}
	defer conn.Close()

	username := r.URL.Query().Get("user")
	if username == "" {
		username = "anonymous"
	}

	room.mu.Lock()
	room.clients[conn] = username
	room.mu.Unlock()

	defer func() {
		room.mu.Lock()
		delete(room.clients, conn)
		room.mu.Unlock()
	}()

	for {
		var msg BidMessage
		err := conn.ReadJSON(&msg)
		if err != nil {
			break
		}

		if msg.Action == "bid" {
			// Each WebSocket message spawns concurrent processing
			go func(user string, amount float64) {
				success, result := room.placeBid(user, amount)
				if success {
					broadcastMsg := fmt.Sprintf(`{"event":"new_bid","user":"%s","amount":%.2f}`, user, amount)
					room.broadcast([]byte(broadcastMsg))
				} else {
					conn.WriteJSON(map[string]string{"error": result})
				}
			}(msg.User, msg.Amount)
		}
	}
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", handleHealth)
	log.Println("Auction WebSocket server starting on :8080")
	log.Fatal(http.ListenAndServe(":0.0.0.0:8080", nil))
}
